    "/v1/catalog/device-views/refresh": {
      "post": {
        "operationId": "requestDeviceViewRefresh",
        "description": "Authenticated local owner only, within configured backend authority. Request bounded supported metadata refresh; never accept asserted facts, available flags, arbitrary probes or permission changes. Startup/event refresh uses the same internal coordinator. No HTTP service is implemented. After scope authorization, missing/malformed/mismatching strong current-status ETag returns428/400/412. Matched refresh atomically increments epoch and marks stale, including bootstrap; no duplicate stale token can be admitted. Exact dv2 syntax in API-CONTRACT.md.",
        "security": [
          {
            "catalogAuth": [
              "catalog:admin"
            ]
          }
        ],
        "parameters": [
          {
            "name": "If-Match",
            "in": "header",
            "required": true,
            "schema": {
              "type": "string",
              "pattern": "^\"dv2:[0-9a-f]{64}:(0|[1-9][0-9]*):(0|[1-9][0-9]*):(0|[1-9][0-9]*):(0|[1-9][0-9]*):[0-9a-f]{64}\"$"
            }
          }
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/DeviceRefreshRequest"
              }
            }
          }
        },
        "responses": {
          "202": {
            "description": "Bounded internal refresh queued; epoch incremented and previous view stale",
            "headers": {
              "ETag": {
                "required": true,
                "description": "New current-view token",
                "schema": {
                  "type": "string",
                  "pattern": "^\"dv2:[0-9a-f]{64}:(0|[1-9][0-9]*):(0|[1-9][0-9]*):(0|[1-9][0-9]*):(0|[1-9][0-9]*):[0-9a-f]{64}\"$"
                }
              }
